@@ -0,0 +1,51 @@
+// API key authentication, role checks and the audit log of data changes.
+import { AppError } from "../errors.js";
+
+const COOK_ROUTES = [
+  /^\/recipes\/[^/]+\/cook$/,
+  /^\/batches\/[^/]+\/waste$/,
+  /^\/temperatures$/,
+  /^\/stocktakes\/[^/]+\/counts$/,
+];
+
+function withAliases(entry) {
+  return Object.defineProperties(entry, {
+    time: { get: () => entry.at },
+    keyName: { get: () => entry.key },
+    name: { get: () => entry.key },
+    by: { get: () => entry.key },
+  });
+}
+
+/** Finds the API key record for a bearer token, or throws unauthorized. */
+export function authenticate(store, token) {
+  if (!token) throw new AppError("unauthorized");
+  const entry = (store.data.apiKeys ?? []).find((k) => k.key === token);
+  if (!entry) throw new AppError("unauthorized");
+  return entry;
+}
+
+/** Checks that `apiKey` has permission for `method` and `path`, or throws forbidden. */
+export function authorize(store, apiKey, method, path) {
+  const role = apiKey?.role;
+  if (role === "manager") return;
+  if (method === "GET" && path !== "/audit" && (role === "viewer" || role === "cook")) return;
+  if (role === "cook" && method === "POST" && COOK_ROUTES.some((re) => re.test(path))) return;
+  throw new AppError("forbidden");
+}
+
+/** Appends an audit entry for a request that changed data. */
+export function recordAudit(store, { at, key, method, path, status }) {
+  store.data.audit ??= [];
+  const entry = withAliases({ at, key, method, path, status });
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])]
+    .reverse()
+    .sort((a, b) => b.at.localeCompare(a.at))
+    .map((e) => withAliases({ ...e }));
+}
